import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/painting.dart';

/// Pre-encoded PNG bytes of cilalutask_logo.png ensuring instant zero-latency
/// rendering on the very first frame of [SplashScreen], even before async
/// AssetBundle decoding completes or during hot-reload sessions.
final MemoryImage kCilalutaskLogoMemoryImage = MemoryImage(
  kCilalutaskLogoBytes,
);

/// Warms up [kCilalutaskLogoMemoryImage] in [PaintingBinding.instance.imageCache]
/// so [SplashScreen] renders the logo synchronously on frame 0.
Future<void> precacheLogoBytes() async {
  try {
    final completer = Completer<void>();
    final stream = kCilalutaskLogoMemoryImage.resolve(ImageConfiguration.empty);
    late final ImageStreamListener listener;
    listener = ImageStreamListener(
      (ImageInfo info, bool synchronousCall) {
        if (!completer.isCompleted) completer.complete();
        stream.removeListener(listener);
      },
      onError: (Object exception, StackTrace? stackTrace) {
        if (!completer.isCompleted) completer.complete();
        stream.removeListener(listener);
      },
    );
    stream.addListener(listener);
    await completer.future.timeout(
      const Duration(milliseconds: 400),
      onTimeout: () {},
    );
  } catch (_) {}
}

final Uint8List kCilalutaskLogoBytes = base64Decode(
  '',
);
